'use strict';
document.getElementById('year').textContent=new Date().getFullYear();
let activeDialog=null, returnFocus=null;
function showDialog(id){returnFocus=document.activeElement;activeDialog=document.getElementById(id);activeDialog.classList.add('open');document.body.style.overflow='hidden';activeDialog.querySelector('button,input,a').focus();}
function hideDialog(){if(!activeDialog)return;activeDialog.classList.remove('open');activeDialog=null;document.body.style.overflow='';returnFocus?.focus();}
function toggleMenu(open){open?showDialog('menu'):hideDialog();}
function openEnquiry(){showDialog('enquiry');}
function closeEnquiry(){hideDialog();}
document.addEventListener('keydown',e=>{if(!activeDialog)return;if(e.key==='Escape')hideDialog();if(e.key==='Tab'){const items=[...activeDialog.querySelectorAll('button,a[href],input,select,textarea,summary')].filter(x=>x.getClientRects().length);const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
document.getElementById('enquiry').addEventListener('click',e=>{if(e.target.id==='enquiry')hideDialog();});
const trip=document.getElementById('tripform');
function prepareMessage(){const value=id=>document.getElementById(id).value.trim();const message='Hello Modi Holidays, I would like to plan a journey.\nName: '+value('customer-name')+'\nTravellers: '+value('travellers')+'\nTravel style: '+value('kind')+'\nDestination / package: '+value('where')+'\nDates: '+value('when')+'\nNotes: '+value('details');const url='https://wa.me/917666018401?text='+encodeURIComponent(message);const link=document.getElementById('send-enquiry');link.href=url;link.hidden=false;const copy=document.getElementById('message-copy');copy.value=message;copy.hidden=false;document.getElementById('copy-enquiry').hidden=false;return url;}
trip.addEventListener('submit',e=>{e.preventDefault();if(!trip.reportValidity())return;const url=prepareMessage();document.getElementById('status').textContent='Review and send your message in WhatsApp. If it did not open, use the link or copy the message below. Nothing has been saved on this website.';window.open(url,'_blank','noopener,noreferrer');});
trip.addEventListener('input',()=>{if(!document.getElementById('message-copy').hidden)prepareMessage();});
document.getElementById('copy-enquiry').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(document.getElementById('message-copy').value);document.getElementById('status').textContent='Message copied. Paste it into WhatsApp when ready.';}catch{document.getElementById('message-copy').focus();document.getElementById('message-copy').select();document.getElementById('status').textContent='Please copy the selected message manually.';}});
const catalogue=JSON.parse(document.getElementById('catalogue-data').textContent);
const search=document.getElementById('catalogue-search');
search.addEventListener('submit',e=>{e.preventDefault();const destination=document.getElementById('holiday-destination').value;const category=document.getElementById('holiday-category').value;const days=document.getElementById('holiday-duration').value;const results=catalogue.filter(p=>(!destination||p.destination===destination)&&(!category||p.category===category||(category==='Domestic'&&p.category==='Pilgrimage'))&&(!days||parseInt(p.duration,10)===Number(days)));const box=document.getElementById('search-results');box.replaceChildren();document.getElementById('search-status').textContent=results.length?`${results.length} matching holidays. Select a journey to view its full itinerary.`:'No holidays match these filters. Try another destination or duration.';for(const p of results){const card=document.createElement('article');card.className='search-result';const meta=document.createElement('p');meta.textContent=p.destination+' · '+p.duration+' · '+p.id;const heading=document.createElement('h3');heading.textContent=p.name;const link=document.createElement('a');link.href='tours/'+p.slug+'.html';link.textContent='View itinerary ↗';card.append(meta,heading,link);box.append(card);}});
